/**
 * Shared build-cache manifest for compiled token maps. Persona cards compile their
 * trait maps on first use, so the persona loader warms this cache at module load
 * (see personas.mjs) to keep the first request fast.
 */
const compiled = new Map();

/**
 * Compile a token map into its stable serialized form and cache it by key. Named
 * for its original CSS-variable use; it is a general token-map cache.
 *
 * @param {string} key - Cache key (persona id).
 * @param {Record<string, string>} tokens - Token names mapped to raw values.
 * @returns {string} The serialized token map.
 */
export function cssVarMap(key, tokens) {
  const cached = compiled.get(key);
  if (cached !== undefined) {
    return cached;
  }
  const value = Object.entries(tokens)
    .map(([name, token]) => `${name}:${token}`)
    .join(";");
  compiled.set(key, value);
  return value;
}
